function getFilmBalance() {
    const v = parseFloat(localStorage.getItem('film_balance') || '0');
    return Number.isFinite(v) ? v : 0;
}

// 馃攧 浜戠浣欓鍚屾鐘舵€?let __cloudBalanceSyncPending = false;
let __lastCloudBalanceSyncAt = 0;
const __CLOUD_BALANCE_SYNC_INTERVAL = 30000; // 30绉掑唴涓嶉噸澶嶅悓姝?
/**
 * 馃攧 浠庝簯绔埛鏂拌兌鐗囦綑棰濓紝纭繚鏈湴涓庢湇鍔″櫒涓€鑷? * @param {boolean} force - 鏄惁寮哄埗鍒锋柊锛堝拷鐣ラ槻鎶栵級
 * @returns {Promise<number|null>} 鏂颁綑棰濇垨null
 */
async function refreshFilmBalanceFromCloud(force = false) {
    try {
        // 闃叉姈锛?0绉掑唴涓嶉噸澶嶅悓姝ワ紙闄ら潪寮哄埗锛?        const now = Date.now();
        if (!force && (now - __lastCloudBalanceSyncAt) < __CLOUD_BALANCE_SYNC_INTERVAL) {
            return null;
        }
        if (__cloudBalanceSyncPending) return null;
        
        __cloudBalanceSyncPending = true;
        
        if (typeof NVAuth === 'undefined') {
            __cloudBalanceSyncPending = false;
            return null;
        }
        const user = await NVAuth.getCurrentUser();
        if (!user?.id) {
            __cloudBalanceSyncPending = false;
            return null;
        }

        const res = await fetch('/api/supabase-proxy', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'getProfile', userId: user.id })
        });
        const data = await res.json().catch(() => ({}));
        
        __cloudBalanceSyncPending = false;
        __lastCloudBalanceSyncAt = now;
        
        if (res.ok && data.success && typeof data.quotaBalance === 'number') {
            const newBalance = data.quotaBalance;
            const oldBalance = getFilmBalance();
            
            // 鏇存柊鏈湴缂撳瓨
            localStorage.setItem('film_balance', String(newBalance));
            localStorage.setItem('cloud_film_balance', String(newBalance));
            localStorage.setItem('cloud_balance_sync_at', String(now));
            
            // 鍚屾浼氬憳绫诲瀷
            if (data.membershipType) {
                localStorage.setItem('membership_type', data.membershipType);
            }
            
            if (oldBalance !== newBalance) {
                console.log(`馃攧 [浜戠浣欓鍚屾] ${oldBalance} 鈫?${newBalance}`);
            }
            try { updateUsageDisplay(); } catch (e) { }
            return newBalance;
        }
        return null;
    } catch (e) {
        __cloudBalanceSyncPending = false;
        console.warn('鈿狅笍 [浜戠浣欓鍚屾澶辫触]', e?.message);
        return null;
    }
}

