    let imageUrls = undefined;
    let action = 'image';
    
    // 澶氬浘鍙傝€冩ā寮?(1-3寮?
    if (refImages && Array.isArray(refImages) && refImages.length >= 2) {
        // Qwen-Image-Edit 鏈€澶氭敮鎸?寮犲弬鑰冨浘
        imageUrls = refImages.slice(0, 3);
        action = 'image2image';
        console.log(`馃幁 [涓囪薄Max] 澶氬浘缂栬緫妯″紡: ${imageUrls.length}寮犲弬鑰冨浘`);
    }
