async function __cloudCreateGenerationTask(payload) {
    try {
        if (typeof NVAuth === 'undefined') return null;
        const user = await NVAuth.getCurrentUser();
        if (!user) return null;
        const res = await fetch('/api/supabase-proxy', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'createGenerationTask', userId: user.id, ...payload })
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok || !data.success) return null;
        return data.taskId || null;
    } catch (e) {
        return null;
    }
}

async function __cloudUpdateGenerationTask(taskId, patch) {
    try {
        if (!taskId) return false;
        if (typeof NVAuth === 'undefined') return false;
        const user = await NVAuth.getCurrentUser();
        if (!user) return false;
        const res = await fetch('/api/supabase-proxy', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'updateGenerationTask', userId: user.id, taskId, patch: patch || {} })
        });
        const data = await res.json().catch(() => ({}));
        return !!(res.ok && data.success);
    } catch (e) {
        return false;
    }
}

async function __cloudGetGenerationTask(taskId) {
    try {
        if (!taskId) return null;
        if (typeof NVAuth === 'undefined') return null;
        const user = await NVAuth.getCurrentUser();
        if (!user) return null;
        const res = await fetch('/api/supabase-proxy', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'getGenerationTask', userId: user.id, taskId })
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok || !data.success) return null;
        return data.task || null;
    } catch (e) {
        return null;
    }
}

function __sanitizeTaskRequestBody(body) {
    try {
        const copy = JSON.parse(JSON.stringify(body || {}));
        if (typeof copy.image_url === 'string' && copy.image_url.startsWith('data:') && copy.image_url.length > 5000) {
            copy.image_url = null;
            copy.__refImageStripped = true;
        }
        if (Array.isArray(copy.image_urls)) {
            const hasLarge = copy.image_urls.some(u => typeof u === 'string' && u.startsWith('data:') && u.length > 5000);
            if (hasLarge) {
                copy.image_urls = null;
                copy.__refImagesStripped = true;
            }
        }
        return copy;
    } catch (e) {
        return null;
    }
}

