    // --- Scene Images Column (鍥剧敓瑙嗛妯″紡涓撶敤) ---
    const isImageToVideoMode = idea.generationMode === 'banana-image-to-video' || idea.generationMode === 'image-to-video' || idea.generationMode === 'banana-grid-to-video';
    const sceneImages = idea.sceneImages || [];
    let sceneImagesHTML = '';
