/**
 * 鉁忥笍 鑾峰彇鐢绘澘鑺傜偣鐨勫浘鍍忔暟鎹紙渚涘叾浠栬妭鐐逛娇鐢級
 */
window.getSketchpadImage = function (nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (node && node.type === 'sketchpad' && node.data.drawingData) {
        return node.data.drawingData;
    }
    return null;
};

/**
 * 鉁忥笍 鍦ㄦ寚瀹氫綅缃坊鍔犵敾鏉胯妭鐐? */
function addSketchpadNodeAt(screenX, screenY) {
    if (isCreatingNode) return;
    isCreatingNode = true;

    const p = getCanvasWorldPointFromScreen(screenX, screenY);
    const baseX = p.x;
    const baseY = p.y;

    // 馃Р 浣跨敤鎺掓枼绠楁硶
    const pos = findNonOverlappingPosition(baseX, baseY, 350, 400);

    const sourceId = tempConnection ? tempConnection.sourceId : null;
    console.log('鉁忥笍 鍒涘缓鎵嬬粯鐢绘澘鑺傜偣:', { x: pos.x, y: pos.y, sourceId });
    createSketchpadNode(pos.x, pos.y, sourceId);

    setTimeout(() => {
        isCreatingNode = false;
    }, 500);
}

/**
 * 鉁忥笍 宸ュ叿鏍忔寜閽細鍦ㄧ敾甯冧腑澶垱寤虹敾鏉胯妭鐐? */
window.addSketchpadNodeAtCenter = function () {
    const containerEl = document.getElementById('taskCanvasContainer') || document.getElementById('taskCanvas');
    const rect = containerEl.getBoundingClientRect();
    addSketchpadNodeAt(rect.left + rect.width / 2, rect.top + rect.height / 2);
};

