/**
 * 馃幍 搴旂敤椋庢牸妯＄増锛堝彧璁剧疆椋庢牸鏍囩锛屼笉褰卞搷棰勮锛? */
window.musicNodeApplyStyleTemplate = function (nodeId, templateKey) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    const template = SUNO_STYLE_TEMPLATES[templateKey];
    if (!template) return;

    // 馃敡 淇锛氶鏍兼爣绛捐拷鍔犲埌鐜版湁鏍囩锛岃€屼笉鏄浛鎹?    const existingTags = String(node.data.tags || '').trim();
    const newTags = template.tags;
    
    // 濡傛灉宸叉湁鏍囩锛岃拷鍔犳柊鏍囩锛堝幓閲嶏級
    if (existingTags) {
        const existingSet = new Set(existingTags.split(',').map(t => t.trim().toLowerCase()));
        const newTagsArr = newTags.split(',').map(t => t.trim()).filter(t => !existingSet.has(t.toLowerCase()));
        node.data.tags = existingTags + (newTagsArr.length ? ', ' + newTagsArr.join(', ') : '');
    } else {
        node.data.tags = newTags;
    }
    
    node.data.selectedStyle = templateKey;
    renderCanvas();
    showToast(`宸插簲鐢ㄩ鏍? ${template.name}`);
};

/**
 * 馃幍 搴旂敤棰勮妯＄増锛堣缃璁炬彁绀鸿瘝锛屼笉瑕嗙洊椋庢牸鏍囩锛? */
