window.addPromptWorkshopAtCenter = function () {
    const container = document.getElementById('taskCanvas');
    const rect = container.getBoundingClientRect();
    const scale = window.getCurrentScale ? window.getCurrentScale() : 1;
    const x = (rect.width / 2) / scale;
    const y = (rect.height / 2) / scale;
    const node = createKnollingNodeData(x, y);
    flowNodes.push(node);
    try { window.__rrSuppressAutoFocusTaskWindow && window.__rrSuppressAutoFocusTaskWindow(1200); } catch (e) { }
    renderCanvas();
    try { window.__rrFocusCanvasOnNode && window.__rrFocusCanvasOnNode(node, { animate: false }); } catch (e) { }
    saveIdeasToHistory();
};

