/**
 * 馃敜 鏄剧ず鏂囧瓧杈撳叆瀵硅瘽妗嗭紙鐢ㄤ簬鐢诲竷鏂囧瓧鏍囨敞锛? * @param {number} x - 鐐瑰嚮浣嶇疆X
 * @param {number} y - 鐐瑰嚮浣嶇疆Y  
 * @param {string} color - 鏂囧瓧棰滆壊
 * @param {number} size - 绗斿埛澶у皬锛堢敤浜庤绠楀瓧浣撳ぇ灏忥級
 * @param {function} callback - 鍥炶皟鍑芥暟锛屼紶鍏ヨ緭鍏ョ殑鏂囧瓧
 */
function showTextInputDialog(x, y, color, size, callback) {
    // 绉婚櫎宸插瓨鍦ㄧ殑瀵硅瘽妗?    const existing = document.getElementById('text-input-dialog');
    if (existing) existing.remove();

    // 鍒涘缓瀵硅瘽妗?    const dialog = document.createElement('div');
    dialog.id = 'text-input-dialog';
    dialog.style.cssText = `
        position: fixed;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        background: #1a1a2e;
        border: 2px solid ${color};
        border-radius: 12px;
        padding: 16px;
        z-index: 10000;
        box-shadow: 0 8px 32px rgba(0,0,0,0.5);
        min-width: 300px;
    `;

    dialog.innerHTML = `
        <div style="color: #fff; font-size: 14px; margin-bottom: 12px; font-weight: bold;">
            馃敜 杈撳叆鏂囧瓧鏍囨敞
        </div>
        <input type="text" id="text-input-field" placeholder="杈撳叆瑕佹坊鍔犵殑鏂囧瓧..." 
            style="width: 100%; padding: 10px; border: 1px solid #444; border-radius: 6px; 
                   background: #222; color: ${color}; font-size: 16px; font-weight: bold;
                   box-sizing: border-box;">
        <div style="display: flex; gap: 8px; margin-top: 12px; justify-content: flex-end;">
            <button id="text-cancel-btn" style="padding: 8px 16px; background: #444; color: #fff; 
                    border: none; border-radius: 6px; cursor: pointer;">鍙栨秷</button>
            <button id="text-confirm-btn" style="padding: 8px 16px; background: ${color}; color: #fff; 
                    border: none; border-radius: 6px; cursor: pointer; font-weight: bold;">纭畾</button>
        </div>
    `;

    document.body.appendChild(dialog);

    const inputField = document.getElementById('text-input-field');
    const confirmBtn = document.getElementById('text-confirm-btn');
    const cancelBtn = document.getElementById('text-cancel-btn');

    // 鑷姩鑱氱劍
    setTimeout(() => inputField.focus(), 50);

    // 纭畾鎸夐挳
    confirmBtn.addEventListener('click', () => {
        const text = inputField.value;
        dialog.remove();
        if (callback) callback(text);
    });

    // 鍙栨秷鎸夐挳
    cancelBtn.addEventListener('click', () => {
        dialog.remove();
        if (callback) callback(null);
    });

    // 鍥炶溅纭
    inputField.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
            const text = inputField.value;
            dialog.remove();
            if (callback) callback(text);
        } else if (e.key === 'Escape') {
            dialog.remove();
            if (callback) callback(null);
        }
    });

    // 鐐瑰嚮澶栭儴鍏抽棴
    dialog.addEventListener('mousedown', (e) => e.stopPropagation());
}

window.showTextInputDialog = showTextInputDialog;

// ==================== Connection Logic (Bezier Path) ====================

function calculateBezierPath(start, end) {
    const dx = end.x - start.x;
    const dist = Math.sqrt(dx * dx + (end.y - start.y) * (end.y - start.y));
    const cp1x = start.x + Math.min(dist, 100); // Control point 1
    const cp1y = start.y;
    const cp2x = end.x - Math.min(dist, 100); // Control point 2
    const cp2y = end.y;

    return `M ${start.x} ${start.y} C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${end.x} ${end.y}`;
}

