window.setPaymentTab = function (tab) {
    const t = String(tab || 'recharge');
    const btnRecharge = document.getElementById('paymentTabRecharge');
    const btnMember = document.getElementById('paymentTabMember');
    const panelRecharge = document.getElementById('paymentRechargePanel');
    const panelMember = document.getElementById('paymentMemberPanel');
    const modal = document.getElementById('paymentModal');
    const footerBtn = modal ? modal.querySelector('.modal-footer button') : null;

    const isMember = (t === 'member');
    if (panelRecharge) panelRecharge.style.display = isMember ? 'none' : '';
    if (panelMember) panelMember.style.display = isMember ? '' : 'none';

    const activeStyle = 'background: var(--accent-gold); color: #000; font-weight: 900; border: none;';
    const idleStyle = '';
    if (btnRecharge) btnRecharge.style.cssText = `${btnRecharge.style.cssText};${isMember ? idleStyle : activeStyle}`;
    if (btnMember) btnMember.style.cssText = `${btnMember.style.cssText};${isMember ? activeStyle : idleStyle}`;

    if (footerBtn) footerBtn.style.display = isMember ? 'none' : '';

    try {
        const lv = Number.isFinite(Number(window.currentMembershipLevel))
            ? Number(window.currentMembershipLevel)
            : Number(localStorage.getItem('membership_level'));
        renderMemberLevelGrid(Number.isFinite(lv) ? lv : 0);
        if (isMember) {
            // 姣忔鎵撳紑浼氬憳tab閮藉埛鏂颁竴涓嬩細鍛樹腑蹇冪姸鎬侊紙閬垮厤缂撳瓨瀵艰嚧鏄剧ず涓嶅锛?            try { Promise.resolve().then(() => updateMemberStatus()); } catch (e) { }
            try { renderMembershipPurchaseOptions(); } catch (e) { }
        }
    } catch (e) { }
};

let __rrActivityHeartbeatTimer = null;

async function __rrSendActivityHeartbeat(deltaSeconds) {
    try {
        if (document.hidden) return;
        if (typeof NVAuth === 'undefined') return;
        const user = await NVAuth.getCurrentUser();
        if (!user) return;
        await fetch('/api/supabase-proxy', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                action: 'activityHeartbeat',
                userId: user.id,
                seconds: Math.max(10, Math.min(300, Number(deltaSeconds) || 60))
            })
        });
    } catch (e) { }
}

function startUserActivityHeartbeat() {
    try {
        if (__rrActivityHeartbeatTimer) return;
        const intervalMs = 60 * 1000;
        __rrSendActivityHeartbeat(60);
        __rrActivityHeartbeatTimer = setInterval(() => __rrSendActivityHeartbeat(60), intervalMs);
        document.addEventListener('visibilitychange', () => {
            if (!document.hidden) __rrSendActivityHeartbeat(30);
        });
    } catch (e) { }
}

