window.showTaskError = function (id) {
    const idea = ideas.find(i => i.id === id);
    if (!idea) return;

    // 鏀堕泦鎵€鏈夐敊璇棩蹇?    const logs = (idea.stepLogs || []).filter(l => l.status === 'error' || l.status === 'failed');
    if (logs.length === 0 && idea.status !== 'failed') {
        // 濡傛灉娌℃湁鏄惧紡閿欒涓旂姸鎬佷笉鏄け璐ワ紝鏄剧ず鏈€杩戞棩蹇?        alert('褰撳墠浠诲姟鐘舵€佹甯竆n\n鏈€鏂版棩蹇楋細\n' + (idea.stepLogs && idea.stepLogs.length ? idea.stepLogs[idea.stepLogs.length - 1].message : '鏃犳棩蹇?));
        return;
    }

    const errorMsg = logs.length > 0 ? logs.map(l => `[${new Date(l.time).toLocaleTimeString()}] ${l.message}`).join('\n') : '鏈煡閿欒锛岃妫€鏌ユ帶鍒跺彴';
    alert(`鉂?浠诲姟鎵ц鍑洪敊\n\n${errorMsg}`);
};

