function __rrGetCanvasCenterWorldPoint() {
    try {
        const container = document.getElementById('taskCanvasContainer');
        const rect = container ? container.getBoundingClientRect() : null;
        const cx = rect ? (rect.left + rect.width / 2) : (window.innerWidth / 2);
        const cy = rect ? (rect.top + rect.height / 2) : (window.innerHeight / 2);
        if (typeof getCanvasWorldPointFromScreen === 'function') {
            return getCanvasWorldPointFromScreen(cx, cy);
        }
        return { x: 120, y: 120 };
    } catch (e) {
        return { x: 120, y: 120 };
    }
}

async function openWritingProjectInCanvas(projectId) {
    const pid = String(projectId || '').trim();
    if (!pid) return;

    let node = null;
    try {
        node = flowNodes.find(n => n && n.type === 'writing' && String(n.data?.projectId || '').trim() === pid);
    } catch (e) {
        node = null;
    }

    if (!node) {
        const p = __rrGetCanvasCenterWorldPoint();
        node = createWritingNodeData(p.x - 260, p.y - 220);
        node.data.projectId = pid;
        flowNodes.push(node);
        renderCanvas();
        saveIdeasToHistory();
    }

    await loadWritingNodeProject(node.id, pid);
}

window.openWritingProjectInCanvas = openWritingProjectInCanvas;

function createWritingNodeData(x, y, novelConfig = null) {
    return {
        id: 'writing_' + Date.now(),
        type: 'writing',
        x,
        y,
        width: 560,
        height: 560,
        data: {
            projectId: '',
            projectTitle: '',
            chapters: [],
            currentChapterId: '',
            currentChapterVersion: null,
            chapterTitle: '',
            chapterContent: '',
            status: '',
            novelConfig: novelConfig || { topic: '', genre: '', num_chapters: 10, word_number: 2000, filepath: '' }
        }
    };
}

