function updateWritingNodeField(nodeId, field, value) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    if (!node.data) node.data = {};
    node.data[field] = String(value ?? '');
    try {
        if (!window.__rrWritingNodeSaveTimers) window.__rrWritingNodeSaveTimers = new Map();
        const m = window.__rrWritingNodeSaveTimers;
        const prev = m.get(nodeId);
        if (prev) clearTimeout(prev);
        m.set(nodeId, setTimeout(() => {
            try { saveIdeasToHistory(); } catch (e) { }
        }, 450));
    } catch (e) { }
}

